// Grafana's API root is "" on prod and "/grafana" on staging; appSubUrl carries
// it, so one file is correct in both. The call goes through Grafana's datasource
// proxy, which attaches the scoped DevLake API key server-side and strips browser
// cookies -- that keeps the key out of the browser and stops DevLake's CSRF check
// engaging. See grafana/provisioning/datasources/datasource.yml.
const base = window.grafanaBootData?.settings?.appSubUrl || '';
const path = base + '/api/datasources/proxy/uid/devlake-api/rest/user-project-mappings/';
return (async () => {
  const res = await fetch(path + encodeURIComponent('${userLogin}'), {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ projectName: '${project}' }),
  });
  if (res.ok) {
    context.grafana.notifySuccess(['Mapping Added', '${userLogin} → ${project}']);
    context.grafana.refresh();
  } else {
    context.grafana.notifyError(['Error', 'HTTP ' + res.status + ': ' + (await res.text())]);
  }
})();

// Grafana's API root is "" on prod and "/grafana" on staging; appSubUrl carries
// it, so one file is correct in both. The call goes through Grafana's datasource
// proxy, which attaches the scoped DevLake API key server-side and strips browser
// cookies -- that keeps the key out of the browser and stops DevLake's CSRF check
// engaging. See grafana/provisioning/datasources/datasource.yml.
const base = window.grafanaBootData?.settings?.appSubUrl || '';
const path = base + '/api/datasources/proxy/uid/devlake-api/rest/user-project-mappings/';
return (async () => {
  const res = await fetch(
    path + encodeURIComponent('${userLogin}') + '/' + encodeURIComponent('${project}'),
    { method: 'DELETE', credentials: 'same-origin' },
  );
  if (res.ok) {
    context.grafana.notifySuccess(['Mapping Removed', '${userLogin} → ${project}']);
    context.grafana.refresh();
  } else {
    context.grafana.notifyError(['Error', 'HTTP ' + res.status + ': ' + (await res.text())]);
  }
})();
